INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('allosaurus', 'Allosaurus', 'animal', 'rifts', 0, 'Animal predator, considered Miscreant or Diabolic', '{"IQ":"1D4+3","ME":"4+1D6","MA":"6+1D6","PS":"30+1D6","PP":"15+2D6","PE":"19+1D6","PB":"4+2D6","Spd":"28+2D6 min 30"}', NULL, NULL, '1D4x100', '3D6', NULL, 'Mega-Damage by location: Head 100; Forelimbs (2) 40 each; Hind Limbs (2) 150 each; Tail 90; Main Body 1D4x100. Supernatural P.S. and P.E. I.Q. is medium animal intelligence. Minimum speed 30 (23 mph/36.8 km); most have 34 (26 mph/41.6 km).', NULL, 15, '{"attacks":4,"initiative":2,"strike":3,"dodge":2,"roll":1}', '+9 to save vs Horror Factor. All in addition to possible attribute bonuses.', 'Track by smell 70%; Camouflage 65% and Prowl 55% (some richly patterned individuals: Camouflage 80% and Prowl 65%); Land Navigation 90%.', 'Holds its top speed for about 25 minutes. Keen nose. Its patterned hide lets it lie in ambush. Cannot swim or climb. The G.M. decides whether invisible Allosaurs exist; if they do, one can turn invisible at will for up to an hour while lying in wait, and the invisibility ends the moment it attacks or moves quickly.', 'Heals 6D6 M.D. per hour on a ley line.', 'None.', '20 feet (6.1 m) long from snout to tail tip, 8-10 feet (2.4-3 m) tall', '4000 lbs (1800 kg)', '20-26 years', 'Forests and marshy lowlands, mostly at their edges; chiefly the forests of North and South Carolina', 'None, except pack-mates when they form packs', 'Other predators, and anything it can eat', 'None; animal.', 'A theropod about half a T-Rex''s size, with horns, fins and ridges on its skull and grasping forearms, often mistaken for a young Tyrannosaur. Mostly a lone hunter and scavenger; Simvan sometimes ride them and the Splugorth put them in the arena.', 'Rifts World Book 26: Dinosaur Swamp p.15-16'),
('ankylosaurus', 'Ankylosaurus', 'animal', 'rifts', 0, 'Animal, considered Anarchist', '{"IQ":"1D4","ME":"1D6","MA":"1D6+2","PS":"36+2D6","PP":"4+2D6","PE":"24+1D6","PB":"2D6","Spd":"15+1D6 min 16"}', NULL, NULL, '600+1D6x100', '3D6', NULL, 'Mega-Damage by location: Head 150 (small target); Body Spikes (typically 20) 25 each (small); Forelimbs (2) 190 each; Hind Limbs (2) 225 each; Tail 200; Bone-club tail tip 300 (small); Underbelly 200; Main Body 600+1D6x100. A small target takes a called shot at -3 to strike. Supernatural P.S. and P.E. I.Q. is extremely low animal intelligence. Minimum speed 16 (12 mph/19.2 km); most have 18 (14 mph/22.4 km).', NULL, NULL, '{"attacks":3,"initiative":-1,"roll":10}', '+10 to save vs Horror Factor, +10 to roll with impact, -1 on initiative. In addition to possible attribute bonuses. No Horror Factor of its own, though an angry family may warrant a temporary 10.', NULL, 'Tireless: can travel for days without rest and shrugs off great pain. 95% immune to toxins, and any that do work cause a third of the damage and last a third as long. Ordinary sense of smell, but scents a Qink plant up to 5 miles (8 km) off.', 'Impervious to poison, toxins, drugs, acid and disease while on a ley line, and heals within an hour of M.D.C. lost to poison; every penalty and side effect ends on reaching the line.', 'None.', '35 feet (10.6 m) long, 4 feet (1.2 m) tall at the hips', '8000 lbs (3600 kg)', '50-70 years', 'Seldom south and east of the Appalachians; mostly the midlands of North Carolina, South Carolina and northern Georgia, and increasingly the New West and southern Canada', 'None', 'Few large predators trouble an adult; packs of smaller, quicker dinosaurs are the threat', 'None; animal.', 'A heavily plated, spiked plant-eater with a bone-club tail that travels in small family groups, avoids wet ground, and eats the poisonous Qink plant. Its plates are too heavy for armor: on a vehicle or robot they cut speed by 1D4x10%+20%, and a person wearing them moves and uses physical skills at half.', 'Rifts World Book 26: Dinosaur Swamp p.17-18'),
('dilophosaurus', 'Dilophosaurus', 'animal', 'rifts', 0, 'Animal predator, considered Miscreant or Diabolic', '{"IQ":"1D4+3","ME":"3+1D6","MA":"1D6","PS":"14+2D6","PP":"12+2D6","PE":"16+1D6","PB":"14+1D6","Spd":"36+3D6 min 40"}', NULL, NULL, '4D6x10', '1D6x10+10', NULL, 'Mega-Damage by location: Head 55; Tail 50; Neck 60; Hind Limbs (2) 100 each; Forelimbs (2) 45 each; Main Body 4D6x10. Supernatural P.S. I.Q. is medium animal intelligence. Minimum speed 40 (30 mph/48 km); most have 48 (36 mph/57.6 km). Its P.P.E. is unusually high for a creature that is not magical, and nobody knows why.', NULL, 12, '{"attacks":4,"parry":2,"dodge":2}', '+3 to strike with its forelimb claws, +2 to parry, +2 to dodge, +2 to save vs magic and possession. In addition to possible attribute bonuses.', 'Track by sight 55%.', 'Keen eyes. Without a run it jumps 12 feet (3.6 m), upward or forward; a running start doubles the distance.', 'At will on a ley line, the equal of the Chameleon spell cast by a third level practitioner. Bio-regenerates 3D6 M.D. per hour and regrows lost limbs overnight.', 'None.', '20 feet (6.1 m) long from snout to tail tip, 5 feet (1.5 m) tall', '1000 lbs (450 kg)', '30-35 years', 'Marshes and forests, hunting along streams and lakes; mostly Georgia and Florida, thinning to the north and west', 'None', 'Other predators and humanoids', 'None; animal.', 'A long-legged running theropod that kills with its claws more than its small jaws, crowned with paired crests that flush with color. Shy and usually alone, but it fights hard when cornered. A live, uninjured specimen fetches as much as 10,000 credits from arena owners, who match them in cockfight-style bouts.', 'Rifts World Book 26: Dinosaur Swamp p.18-19'),
('pachycephalosaurus', 'Pachycephalosaurus', 'animal', 'rifts', 0, 'Animal, considered Anarchist; aggressive and high strung', '{"IQ":"1D4+2","ME":"9+1D6","MA":"3D6","PS":"21+1D6","PP":"15+1D6","PE":"20+1D6","PB":"12+1D6","Spd":"42+2D6 min 44"}', NULL, NULL, '5D6x10', '2D6', NULL, 'Mega-Damage by location: Head 300; Forelimbs (2) 35 each; Hind Limbs (2) 100 each; Tail 120; Main Body 5D6x10. I.Q. is low animal intelligence. Minimum speed 44 (33 mph/52.8 km); most have 50 (38 mph/60.8 km).', NULL, 12, '{"attacks":4,"strike":2,"dodge":2,"roll":6}', '+2 to strike, +2 to dodge, rising to +4 to dodge while running at 16 mph (25.7 km) or slower and +6 at 17 mph (27.3 km) or faster; +6 to roll with impact, +4 to save vs Horror Factor. In addition to possible attribute bonuses. Horror Factor 12 when charging, 16 when three or more charge together.', 'Swim 75%.', 'Fast runner with good eyesight. A reinforced skeleton absorbs the shock of ramming with its skull. Vulnerability: after a full-strength running head butt it is stunned for one melee action.', 'None.', 'None.', '15 feet (4.6 m) long, 3 feet (0.9 m) tall at the hips and 5-7 feet (1.5-2.1 m) standing erect', '950 lbs (427.5 kg)', '25-30 years', 'Throughout Dinosaur Swamp, most numerous in Georgia, and spreading west to Louisiana; stray herds as far north as the Dakotas. Herds of 6D6+6 (12-42), the largest up to 80', 'Other members of the herd', 'Predators, humanoids, and rivals within the herd', 'None; animal.', 'The Skull Cracker: a two-legged, grayish-green herbivore with a domed, horn-rimmed skull it rams with hard enough to dent M.D.C. armor. Territorial and quick to charge, and 2D4 of the herd follow the first; it leaves a victim that plays dead. An arena pays 13,000 credits for an adult and 16,000 for a more tractable juvenile; a skull fetches about 3,000 for shields and armor.', 'Rifts World Book 26: Dinosaur Swamp p.19-20'),
('sarcosuchus', 'Sarcosuchus', 'animal', 'rifts', 0, 'Animal, considered Anarchist or Miscreant', '{"IQ":"1D4+1","ME":"22+1D6","MA":"4+1D4","PS":"38+2D6","PP":"17+2D6","PE":"20+1D6","PB":"6+1D4","Spd":"8+1D4"}', NULL, NULL, '1D4x100+200', '3D6', NULL, 'Mega-Damage by location: Head 225; Tail 200; Limbs (4) 150 each; Main Body 1D4x100+200. Supernatural P.S. and P.E. I.Q. is low animal intelligence. Average speed 10 (8 mph/12.8 km), but it can gallop in short bursts and lunge at 26 mph (41.6 km).', NULL, 16, '{"attacks":4}', 'On land: +3 to strike, -3 to dodge. In water: +3 on initiative, +4 to strike, +5 to dodge, +1 to save vs poison and disease, +2 to save vs Horror Factor. In addition to possible attribute bonuses.', 'Swimming 90%; Prowl 65% while submerged; Track 65% by sight and smell (+20% following blood in the water); Blend (in and under water) 65%; Camouflage (self) 60%; Detect Ambush 50%.', 'Lives in water and on land like a modern crocodile, driven by a powerful tail; holds its breath for an hour. Good sight and smell. Bursts into a short gallop, and can launch itself out of the water from rest by about three-quarters of its length. Special lunge attack: always its first attack of the round and only after a successful Prowl; near instantaneous, +8 to strike, and only prey with Automatic Dodge can dodge it (after a failed Prowl, prey dodges at +2). It does 2D4x10 M.D., holds the victim, and forces a save vs Horror Factor of 14 or higher. A held victim is dragged under, shaken and rolled for 4D6 M.D. per melee attack; anyone in M.D.C. body armor takes 1D6 S.D.C. for every 5 M.D. inflicted.', 'None.', 'None.', '40 feet (12.2 m) long; the skull alone is 6 feet (1.8 m)', '17,500 lbs (7875 kg)', '100-130 years', 'Rivers, lakes, bays and inlets throughout Dinosaur Swamp, the Atlantic coast and the Gulf of Mexico; most common on the Florida peninsula and the barrier islands', 'None', 'Spinosaurs, sharks and other aquatic predators, and humanoids', 'None; animal.', 'The giant crocodile, an ambush predator that takes anything it can seize, from T-Rex and young sauropods to people in power armor, which some have learned to pry open. It contests the same waters with the Spinosaur and wins in the water. Its whole hide can fetch up to 10,000 credits, and its 1D4x10+18 teeth 100 credits each, used in tooth clubs and Horror Maces.', 'Rifts World Book 26: Dinosaur Swamp p.20-22'),
('sauropod', 'Sauropod', 'animal', 'rifts', 0, 'Animal, considered Anarchist', '{"IQ":"1D4","ME":"2D6+2","MA":"2D6+2","PS":"80+2D6","PP":"2D6+1","PE":"26+1D6","PB":"2D6","Spd":"15+1D6 min 16"}', NULL, NULL, '1D6x100+800', '1D4x10', NULL, 'Mega-Damage by location: Head 100 (small target, called shot at -3 to strike); Neck 300; Legs (4) 400 each; Tail 250; Main Body 1D6x100+800. Supernatural P.S. and P.E. I.Q. is painfully low animal intelligence. Minimum speed 16 (12 mph/19.2 km); most have 18 (14 mph/22.4 km). Its large P.P.E. comes from its size alone.', NULL, 10, '{"attacks":3,"initiative":-4,"dodge":-10,"roll":10}', '-4 on initiative, +15 to save vs Horror Factor, +10 to roll with impact, -10 to dodge, and cannot parry. In addition to possible attribute bonuses. Horror Factor 10 at a distance, 17 when directly beneath it or about to be stepped on.', 'Dowsing 55%, Land Navigation 75%, Identify Plants and Fruits (edible ones) 98%.', 'Gigantic, enduring and almost impossible to stop, with great tolerance for pain. Average sight and hearing, good smell and a very fine sense of taste. Its padded feet feel low vibrations up to 2 miles (3.2 km) away: large animals, explosions, quakes, mining and logging, vehicles, crowds of two dozen or more, and rushing water. Vulnerabilities: slow and ponderous, very dim, and always moving on to browse.', 'Negate Magic and Dispel Magic Barriers, once per 24 hours per animal: as a fifth level practitioner for an adult, second level for an adolescent, not at all for the very young.', 'None.', '80 feet (24.4 m) long from head to tail, 15 feet (4.57 m) tall at the hips', '75,000 lbs (33,750 kg)', '120 years', 'Forest edges, wading deep into the marshes to feed; the whole of Dinosaur Swamp, with younger animals drifting west and small adult herds seen in the Midwest', 'None', 'Few predators threaten an adult, and even packs of smaller, quicker dinosaurs are little danger; humanoid hunting parties and big Raptor packs do take them', 'None; animal.', 'The giant long-necked browsers (Brontosaurs, Brachiosaurs and their kin), the least intelligent of the dinosaurs, migrating constantly in search of food. One carcass can feed a village for a month; the meat sells for 3-5 credits a pound in the ''Burbs but has no market in the Coalition, and they cannot be tamed, farmed or used in an arena.', 'Rifts World Book 26: Dinosaur Swamp p.22-23'),
('scampers', 'Scampers', 'animal', 'rifts', 0, 'Animal, considered Anarchist, but tends to take on its master''s alignment as a pet or familiar', '{"IQ":"1D6+6","ME":"2D6","MA":"4+2D6","PS":"4+1D6","PP":"15+1D6","PE":"9+1D6","PB":"7+1D6","Spd":"24+1D6 min 25"}', NULL, NULL, '3D4+3', '4D6', NULL, 'A minor Mega-Damage creature, hurt by both M.D. and S.D.C. weapons (about 600-1500 S.D.C. on Rifts Earth). In S.D.C. settings it has only 4D6 S.D.C., A.R. 9, and Hit Points equal to its P.E. I.Q. is extremely high animal intelligence. Minimum speed 25 (19 mph/30.4 km); most have 28 (21 mph/33.6 km).', NULL, NULL, '{"attacks":5,"initiative":4,"strike":2,"dodge":6}', '+4 on initiative, +2 to strike, +6 to dodge, -3 to save vs Horror Factor. In addition to possible attribute bonuses. No Horror Factor of its own; a swarm of 20 or more might warrant 8, or 9-13 against someone injured and helpless.', 'Wilderness Survival 90%, Land Navigation 75%, Blend (Camouflage) 60% (+10% alone or in a pair), Prowl 45% (+10% alone), Detect Ambush 65%, Detect Concealment 45%, Climb 60%, Swim 70%, Palming 50%, Escape Artist 45%, Tracking (by sight) 40%; the list prints Detect Ambush a second time at 40%. Track by smell 40% (+15% following blood, rotting meat or another strong scent).', 'Good color vision and hearing, nightvision 15 feet (4.6 m). Jumps 8 feet (2.4 m) upward or 12 feet (3.6 m) forward; a full run adds half again to either. Vulnerability: small and weak, and nearly everything hunts them.', 'Once a day each, at will and without spending its own P.P.E., as a first level practitioner: Death Trance, Chameleon, Cleanse, Mystic Fulcrum and Armor of Ithan.', 'None.', '2-3 feet (0.6-0.9 m) long, 1-1.5 feet (0.3-0.4 m) high', '12-20 lbs (5.4-9 kg)', '18-20 years', 'The eastern seaboard and almost the whole southeast, west to Lone Star and north to New England; scarce in and beyond Michigan and the Magic Zone', 'None beyond its family pack, or its owner and family when kept as a pet or familiar', 'Predators, barbarians, and rival Scamper packs', 'None. The book does not intend them as player characters, but does not forbid a G.M. and player who want to try; they make good pets, watch animals, familiars and NPC companions.', 'Tiny, very dark green, black-striped bipedal omnivores that live in skittish packs, flee at a sound and mob only the weak or dead. Dog-smart when raised alone; some learn voice commands. A barbarian staple: a carcass sells for 20-40 credits, an unmarked hide (soft enough for gloves and clothing) up to 100, and a baby raised as a pet or familiar 200.', 'Rifts World Book 26: Dinosaur Swamp p.23-24'),
('spinosaurus', 'Spinosaurus', 'animal', 'rifts', 0, 'Animal, considered Miscreant or Diabolic', '{"IQ":"1D6+3","ME":"1D6+5","MA":"1D6+6","PS":"1D6+40","PP":"12+2D4","PE":"21+1D6","PB":"2D6","Spd":"25+1D6 min 26"}', NULL, NULL, '1D6x100+50', '4D6', NULL, 'Mega-Damage by location: Head 175; Tail 120; Forelimbs (2) 65 each; Hind Limbs (2) 135 each; Main Body 1D6x100+50; Dorsal Sail 150. Supernatural P.S. and P.E. I.Q. is medium animal intelligence. Minimum speed 26 (20 mph/32 km) running or swimming; most have 30 (23 mph/36.8 km).', NULL, 16, '{"attacks":4}', 'On land: +1 on initiative, +3 to strike, +2 to dodge, +4 to roll with impact. In water: +4 on initiative, +5 to strike, +3 to dodge. In addition to possible attribute bonuses.', 'Swimming 80%; Prowl 50% while submerged; Track 55% by sight and smell (+20% following blood in the water).', 'At home in water and on land; holds its breath for 3 hours. Good sight and smell. The sail sheds or keeps body heat and serves as a threat display. Special lunge attack: always its first attack of the round and only after a successful Prowl; near instantaneous, +6 to strike, and the target is -3 to dodge. It does 1D4x10 M.D., holds the victim, and forces a save vs Horror Factor of 14 or higher; a held victim is dragged under and shaken for 3D6 M.D. per melee attack, and anyone in M.D.C. body armor takes 1D6 S.D.C. for every 5 M.D. Vulnerabilities: poor hearing on land, and the sail is an easy target: each wound to it keeps bleeding for 1D6+3 minutes, losing 3 M.D. a minute, that is once every 4 melee rounds (Rifts G.M. Guide p.36).', 'None.', 'None.', '50 feet (15.2 m) long, 15 feet (4.6 m) tall, 21 feet (6.4 m) to the top of the sail', '8000 lbs (3600 kg)', '90-120 years', 'The eastern coast near the ocean and the river deltas, spreading inland and west as far as the Texas coast and up the Mississippi; seldom far from a large body of water', 'None; usually a lone hunter', 'Other predators, humanoids, and users of magic', 'None; animal.', 'A crocodile-headed dinosaur with a fin-like sail down its back, native to the Mesozoic though the natives think it a demon. An ambush hunter that, unlike a gator, keeps chasing prey up the bank; some have let themselves be caught in order to turn on their captors. Long-lived, so Alchemists of the Federation of Magic and Atlantis want its organs and blood for longevity and healing potions: an unhurt adult brings 25,000 credits, a juvenile half that, organs 300-1000 each and the heart up to 5,000.', 'Rifts World Book 26: Dinosaur Swamp p.24-26'),
('stegosaurus', 'Stegosaurus', 'animal', 'rifts', 0, 'Animal, considered Anarchist or Unprincipled', '{"IQ":"1D4+2","ME":"12+1D6","MA":"11+2D6","PS":"34+1D6","PP":"7+1D6","PE":"21+1D6","PB":"3+2D6","Spd":"15+1D6 min 16"}', NULL, NULL, '1D4x100+160', '4D6+3', NULL, 'Mega-Damage by location: Head 150 (small); Osteoderms/Back Plates (typically 18) 50 each (small); Forelimbs (2) 110 each; Hind Limbs (2) 150 each; Tail 200; Spiked Tail Tip 130 (small); Underbelly 160; Main Body 1D4x100+160. A small target takes a called shot at -3 to strike. Supernatural P.S. and P.E. I.Q. is very low animal intelligence. Minimum speed 16 (12 mph/19.2 km); most have 18 (14 mph/22.4 km).', NULL, NULL, '{"attacks":3,"parry":1,"roll":4,"pull_punch":4}', '+3 to strike with its tail, +1 to parry, +2 to disarm, +4 to pull punch, +4 to roll with impact, +4 to save vs Horror Factor. In addition to possible attribute bonuses. No Horror Factor of its own, though an angry family may warrant a temporary 10-13, depending on how many.', 'Sniffs out the fruit, vegetables and plants it eats, buried roots included, 80%; sniffs out water (about equal to Dowsing) 55%; Land Navigation 70%; Swim 35%.', 'Nearsighted, but hears well and has a very keen nose. Armored by its plates and a flexible spiked tail. Vulnerabilities: a soft underbelly, very low intelligence and speed, and plates that make bright targets when flushed; wounds to them bleed 3 damage per wound every minute (4 melees) (Rifts G.M. Guide p.36).', '+1 to save vs mind control and +2 to save vs possession. Can cast Sense Evil (2) and See the Invisible (4), paying P.P.E. as usual.', 'None.', '30 feet (9.1 m) long, 9 feet (2.7 m) tall at the hips', '6,800 lbs (3060 kg)', '50-60 years', 'Seldom south and east of the Appalachians; mostly the midlands of North Carolina, South Carolina and northern Georgia, and increasingly the New West, Pennsylvania and southern Canada, more so than the Ankylosaur', 'None as such; travels with other herbivores', 'Few predators threaten an adult, though packs of smaller, quicker dinosaurs go for the underbelly; barbarian hunters do the same while working on the plates', 'None; animal.', 'A stooped, slow, four-legged browser with a double row of blood-filled bony plates (osteoderms) that regulate heat and flush with color to show its mood, and a tail usually carrying six spikes in Dinosaur Swamp (four to eight in other kinds). It travels in family herds that take in Ankylosaurs, young sauropods and even Pachycephalosaurs. Its plates mark trails and floor tribal buildings, and its meat sells well.', 'Rifts World Book 26: Dinosaur Swamp p.26-27'),
('azhures', 'Azhures', 'animal', 'rifts', 0, 'Animal, considered Anarchist or Unprincipled', '{"IQ":"1D4+4","ME":"6+1D4","MA":"8+1D4","PS":"4+1D4","PP":"14+1D6","PE":"13+1D6","PB":"20+1D6","Spd":"5+1D4"}', NULL, NULL, '1D6+6', '1D6', NULL, 'A very minor Mega-Damage creature (about 700-1200 S.D.C.), hurt by both M.D. and S.D.C. weapons. In S.D.C. settings it has only 3D6 S.D.C., A.R. 13, and Hit Points equal to its P.E. I.Q. is medium to high animal intelligence. Spd 5+1D4 on the ground (average 7, 5 mph/8 km) and 48+2D6 flying (average 54, 41 mph/65.6 km).', NULL, NULL, '{"attacks":4,"initiative":1,"strike":2,"parry":1,"pull_punch":3}', '+1 on initiative, +2 to strike, +1 to parry, +8 to automatic dodge in flight, +2 to disarm, +3 to pull punch, and charm/impress 80%. In addition to possible attribute bonuses.', NULL, 'A superb flyer with keen eyesight (can spot a rabbit 3 miles/4.8 km away). Special dive bomb: must be its first attack of the round and uses three attacks; +3 on initiative and +4 to strike, 4D6 S.D.C., and small prey is stunned (one action per melee and no combat bonuses for 1D6 rounds). It spends the rest of that round flying clear. Its metal-laced flesh is inedible and builds up into a poison that can cause insanity or death.', 'None.', 'None.', '18-20 inches (0.45-0.50 m) long, 48 inch (1.2 m) wingspan', '12 lbs (5.4 kg), heavy for its size from the metal in its body', '18-24 years', 'The SteelTree forest''s upper branches, seldom straying far from it, though it can live almost anywhere in North America; a chick raised without SteelTree seeds is neither metallic nor Mega-Damage and grows up black, like a large crow', 'None', 'None', 'None; animal.', 'A metallic-blue alien hawk that nests in the SteelTree forest and eats its seeds, which give it its sheen and its minor M.D.C., along with mice, rabbits, snakes and other small game. Prized as a familiar and trained like a falcon by Wilderness Scouts and barbarians; its feathers sell for up to 50 credits each (double in some seasons) for jewelry, clothing and arrow fletching, Eco-Wizard arrows among them. ARCHIE Three has seeded the flocks with robot copies, roughly one in a hundred.', 'Rifts World Book 26: Dinosaur Swamp p.27-28'),
('haunting-child', 'Haunting Child', 'entity', 'rifts', 0, 'Diabolic or Miscreant', '{"IQ":"1D6+6","ME":"1D6","MA":"1D6","PS":"1D6+1","PP":"1D6+1","PE":"N/A","PB":"1D6+6","Spd":"44"}', NULL, NULL, '6D6+6', '4D6', '1D6x10+44', 'M.A. and P.B. are 20 to children under 12. Spd 44 (33 mph/52.8 km). Its M.D.C. can be harmed only by energy weapons, psionics and magic, and emptying it only banishes the creature for 48 hours, after which it returns to its playground, unless it is slain by a magic demon-slaying weapon, a psionic attack (Psi-Swords work well) or the Dessicate the Supernatural spell.', NULL, 13, '{"attacks":4,"strike":1,"dodge":1}', '+1 to strike, +1 to dodge. In addition to possible attribute bonuses. Impervious to bullets, arrows, explosives, punches and other kinetic attacks, and to normal fire, cold, poison and disease; energy weapons do half damage; magic and psionics do full damage.', NULL, 'Runs at 33 mph (52.8 km) and leaps 15 feet (4.6 m) high or across, really hovering a few inches off the ground. Passes through solid objects. Speaks by Telepathic communication though it can also scream, sing and moan. Vulnerabilities: only magic and psionics can slay it, and it attacks only with psionics. Special Mind-Bending Rhymes, sung aloud and telepathically; everyone who hears must save vs psionic attack. Maudlin Despair (10 I.S.P.): victims pity and try to comfort the spirit; while the singing lasts they suffer -2 to every combat bonus, -1 attack per melee, and -3 on saves vs psionic attack; at least half the group must sing and can do nothing else. Trust and Maternal Madness (10 I.S.P.): victims protect the children against everyone, teammates included, for 2D6x10 minutes after the rhymes stop; a child under 12 instead treats them as trusted siblings for 1D6+6 hours, and each seven hours a further ten minutes of singing renews that. Its third power, Steal Life Energy, costs 10 I.S.P.: by touch, save vs psionic attack; each failed save costs the victim 1D6 Hit Points, or one point of P.E. for a Mega-Damage creature with no Hit Points (at P.E. zero, a coma). Lost Hit Points return normally if the victim is rescued alive; P.E. returns one point per 12 hours.', 'None.', 'Master Psionic, I.S.P. 1D6x10+44, all powers at fifth level: Telepathy (unlimited, no I.S.P.), Empathy (4), Empathic Transmission, Fear only (6), Mind Block (4), Presence Sense (4; senses mortals and children only), See Aura (6), See the Invisible (4), Sixth Sense (2), Telekinesis (varies), Telekinetic Push (4).', 'A young child''s, 2 feet (0.6 m) to 4 feet (1.2 m) tall', 'Not applicable', 'Unknown; presumably eternal', 'Ruined schools, playgrounds, suburbs and shopping plazas in Dinosaur Swamp, above all the Horror Forest of Georgia; fewer on the east coast of New York and Maryland. Usually 4 to 20 together; legend says a ruined school or daycare can hold up to 100', 'Other Haunting Children; it tolerates Entities of every kind and shares its playground with them', 'Humans and all mortals, its prey, and above all practitioners of magic and psychics', 'None.', 'By Todd Yoho and Kevin Siembieda. A ghostly, glowing-eyed child in tattered pre-Rifts clothing, maybe an Entity wearing a dead child''s identity, maybe a trapped ghost of the Great Cataclysm. It drains life energy rather than P.P.E., ignores visitors unless its ruins or games are disturbed, and lures living children to keep as playmates until they waste away and join it; after 48 hours a captive no longer tries to escape and must be rescued by an older person. Worth nothing.', 'Rifts World Book 26: Dinosaur Swamp p.28-30'),
('iron-hoof', 'Iron-Hoof', 'animal', 'rifts', 0, 'Animal, considered Anarchist or Unprincipled', '{"IQ":"4+1D4","ME":"4+1D6","MA":"10+1D6","PS":"30+2D6","PP":"14+1D6","PE":"19+1D6","PB":"10+1D6","Spd":"20+1D6"}', NULL, NULL, '75', '4D6', NULL, 'Mega-Damage by location: Head 30 (small target, called shot at -3 to strike); Forelimbs (2) 60 each; Hind Limbs (2) 50 each; Main Body 75. Supernatural P.S. and P.E. I.Q. is medium animal intelligence. Average speed 23 (17 mph/27.2 km).', NULL, 10, '{"attacks":2,"initiative":3,"strike":1,"parry":2,"roll":2}', 'Enraged: +6 on initiative (its hearing makes it nearly impossible to surprise), +3 to strike, +5 to parry, +4 to roll with impact, and 5 attacks per melee instead of two. When not threatened the bonuses are halved, rounded down, as stored. In addition to possible attribute bonuses. Horror Factor 10 only when enraged.', 'Camouflage 50% among SteelTrees.', 'Good color vision and very sharp hearing (it can pick up a person''s breath at 100 feet/30.5 m). Its hide matches the SteelTrees. The sight of a Panthera-Tereon, a humanoid or a predatory dinosaur sends it into a mindless rage in which it fights until the threat is driven off or everything in sight but other Iron-Hoof is dead. Vulnerabilities: a very narrow diet, and slow.', 'None.', 'None.', '14 feet (4.2 m) tall', '1200 lbs (540 kg)', '45-60 years', 'Found only in the SteelTree forest; taken out of it, one survives on other plants for 3 to 4 months at most without fresh SteelTree leaves', 'Other Iron-Hoof', 'Panthera-Tereon, humanoids, and predatory dinosaurs', 'None; animal.', 'A knuckle-walking herbivore built like a gorilla crossed with a horse and a panda, with a horse-like head and huge curved fore-claws that early barbarians took for hooves. Gentle, living in mated pairs and sharing food between families, it eats SteelTree leaves and bark and so is naturally Mega-Damage. Each claw fetches 200-400 credits; a hide vest gives 18+1D6 M.D.C. and is worth 8,000 credits.', 'Rifts World Book 26: Dinosaur Swamp p.30-31'),
('panthera-thrinax', 'Panthera-Thrinax', 'animal', 'rifts', 0, 'Animal, considered Anarchist or Unprincipled', '{"IQ":"1D4+5","ME":"14+1D6","MA":"10+1D6","PS":"18+1D4","PP":"16+1D6","PE":"17+1D4","PB":"15+1D6","Spd":"22+3D6 min 25"}', NULL, NULL, '50+1D6', '1D4x10', NULL, 'Mega-Damage by location: Head 17+1D4 (small target, called shot at -3 to strike); Forelimbs (2) 20 each; Hind Limbs (2) 24+1D4 each; Main Body 50+1D6. Supernatural P.S. and P.E. I.Q. is high animal intelligence. Minimum speed 25 (19 mph/30.4 km); average 31 (23 mph/36.8 km).', NULL, 10, '{"attacks":5,"initiative":3,"strike":2,"dodge":2,"roll":3}', '+3 on initiative, +2 to strike, +4 to strike with its jaws, +2 to dodge, +3 to roll with impact, +4 to save vs Horror Factor, +1 to save vs poisons and disease. In addition to possible attribute bonuses.', 'Swimming 90%, Prowl 65%, Track by smell 80% (+5% following a blood scent).', 'A fast runner and a superb swimmer, with webbed toes for marshy ground. Hunts in packs, typically 3D6 strong. Special leaping throat attack: 4D6 M.D., and on 01-75% the prey goes down with its throat clamped in the jaws, costing it initiative and two melee attacks; on each later melee attack the cat goes on tearing at the neck for 4D6 M.D., until the prey breaks the grip or is incapacitated.', 'None.', 'None.', '9 feet (2.7 m) long, 3 feet (0.9 m) tall at the hips, with a 4 foot (1.2 m) tail', '550 lbs (247.5 kg)', '25 years', 'All over Dinosaur Swamp: lone hunters, mated pairs, family groups (1D4+2), small packs (2D6+3) and medium packs (4D6+6), with the biggest packs (15-30) in the Carolina forests; loners and small packs reach Virginia and Arkansas, usually following herds', 'None beyond its pack, or its owners if domesticated', 'Competing predators', 'None; animal.', 'A leaner, hyena-like relative of the New West''s Panthera-Tereon (a different animal), with a blunt snout and saber teeth, that kills with its jaws rather than its claws and loves the water. Taken as a pup it can be tamed as a hunting animal, watchdog or mount for children and small adults; the extinct Yellow Stinger tribe bred them. A pup under 3 months sells for up to 1000 credits; older ones are too independent to train.', 'Rifts World Book 26: Dinosaur Swamp p.32-33'),
('spitfire-leaper', 'Spitfire Leaper', 'animal', 'rifts', 0, 'Predatory animal, considered Anarchist or Miscreant', '{"IQ":"1D6+5","ME":"12+1D6","MA":"12+1D6","PS":"20+1D6","PP":"21+1D6","PE":"18+1D6","PB":"16+1D4","Spd":"30+2D6"}', NULL, NULL, '80', '4D6', NULL, 'Mega-Damage by location: Head 25 (small); Beak 18 (small); Forelimbs (2) 40 each; Hind Limbs (2) 50 each; Tail 30; Main Body 80. A small target takes a called shot at -3 to strike. I.Q. is high animal intelligence. Spd 30+2D6 running (average 36, 27 mph/43.2 km), 20+1D4 leaping tree to tree (average 22, 17 mph/27.2 km), 10+1D4 brachiating (average 12, 9 mph/14.4 km).', NULL, 11, '{"attacks":4,"initiative":4,"strike":2,"parry":2,"dodge":2,"roll":4}', '+4 on initiative, +2 to strike, parry and dodge, +6 to a leaping dodge, +4 to roll with impact, +3 to save vs Horror Factor. In addition to possible attribute bonuses.', 'Acrobatics 86%, Climbing 96%, Swim 60%, Land Navigation 75%.', 'Hawk-sharp eyes and prehensile clawed hands and feet. Jumps 25 feet (7.6 m) up or forward, double that from a running start, steering through the air on its fan tail in a crude glide, and swings limb to limb. Lives in packs, resists heat and fire, and breathes fire. Special fire ball: 4D6 M.D., range 30 feet (9.1 m), one melee attack each and no more than two a round, used on big prey and threats, never on smaller animals. Special pounce: 2D8 M.D.; on 01-45% the prey is bowled over (losing initiative and one melee attack), and the leaper follows with raking with all four limbs for 5D6 M.D., or all four limbs and the beak for 1D6x10 M.D. Vulnerabilities: a life in the trees risks falls, and its young need particular conditions.', 'Takes half damage from heat and fire attacks.', 'None.', '4 feet 6 inches (1.37 m) long', '100 lbs (45 kg)', '25 years', 'Most common in the swampy forests of Florida, fewer along the Atlantic coast as far north as the old Georgia/South Carolina border; nests high in thick branches in packs of 2-8', 'Other Spitfire Leapers', 'Humanoids and other predators', 'None; animal.', 'A tree-living, bright metallic-green dinosaur-like hunter with dark red scales along its spine, long sloth-clawed arms and a toothless, serrated beak, that drops from the branches onto birds, lizards and small game and coughs baseball-sized fire balls. Seldom attacks humanoids except alone or in groups of four or fewer. A whole hide sells for 1000-2000 credits for decorative armor.', 'Rifts World Book 26: Dinosaur Swamp p.33-34'),
('switchback', 'Switchback', 'animal', 'rifts', 0, 'Animal, considered Anarchist or Miscreant', '{"IQ":"1D4+3","ME":"10+1D6","MA":"2D6","PS":"20+1D6","PP":"22+1D6","PE":"17+1D4","PB":"8+1D6","Spd":"40+1D6"}', NULL, NULL, '112', '3D6', NULL, 'Mega-Damage by location: Head 25 (small target, called shot at -3 to strike); Legs (6) 75 each; Tail 65; Underbelly 45; Main Body 112. Supernatural P.S. and P.E. I.Q. is average animal intelligence. Average speed 43 (32 mph/51.2 km).', NULL, 11, '{"attacks":4,"initiative":2,"strike":3,"parry":3,"dodge":3}', '+2 on initiative, +3 to strike, parry and dodge, +4 to save vs Horror Factor, +8 to save vs poison/toxins and disease. In addition to any possible attribute bonuses. Horror Factor 11, or 13 with its quills raised.', 'Track by scent 65%.', 'A fast runner whose powerful gut digests almost anything organic. Wedge-shaped foot claws dig and grip. Rows of retractable needle quills along its spine spring out when it is angry or scared, lodge in whatever touches them and grow back; with them out it swings its tail like a studded club and charges. Marks its range with a strong musk. Vulnerabilities: poor hearing, a lightly armored underbelly, and a territorial streak that outruns its sense of self-preservation.', 'Completely immune to poison and rotten food eaten on a ley line.', 'None.', '8 feet (2.4 m) long, 3 feet (0.9 m) tall at the hips', '450 lbs (202.5 kg)', '40 years', 'Almost only the foothills of North Carolina, Georgia, Tennessee and Kentucky, north to West Virginia, below the dimensionally unstable mountains whose Rifts keep it fed', 'None', 'Humanoids, other Switchbacks, predators, and nearly anything else', 'None; animal.', 'A long, lean, armor-plated omnivore with a broad flat head, a triangular shearing beak and bone-crushing teeth, that eats anything smaller and slower than itself. Fiercely territorial; mates only one week in three years, after which the male leaves before he is eaten. Its quills and plates make body armor and weapons, and lashed together the quills make good roofing.', 'Rifts World Book 26: Dinosaur Swamp p.34-35'),
('trysia-faerie', 'Trysia Faerie', 'faerie', 'rifts', 1, 'Any, but typically Anarchist (40%) or Miscreant (35%); a player character may be any. An NPC addicted to Lankton''s Knot is always Anarchist (50%) or evil (50%, any)', '{"IQ":"2D6+2","ME":"2D6+1","MA":"2D6+5","PS":"1D6+2","PP":"2D6+8","PE":"2D6+2","PB":"16+1D6","Spd":"4D6"}', NULL, NULL, '2D6+PE', '1D6x10+PE', '2D6+ME', 'Spd 4D6 running, 2D6x10 flying. Can draw P.P.E. from ley lines and other places of power as a practitioner of magic does.', NULL, 8, '{"attacks":3}', '+3 to dodge while flying, +2 to Spell Strength, +3 to save vs magic, +2 to save vs psionics. One not addicted to the plant also gets +1 on initiative, +1 to strike and parry, +2 to dodge (standing or flying) and +2 to roll with impact. In addition to possible attribute bonuses. Attacks per melee: 3, +1 for every three levels of experience.', 'R.C.C. skills: Speaks Faerie/Gobblely 98%, one other Language (+10%), Land Navigation (+10%), Wilderness Survival (+15%), Faerie Lore (+30%), Dance (+15%), Prowl (+20%), Sing (+30%), W.P. Knife, and two more skills with G.M. approval.', 'Flies, sees the invisible, and has a keen nose for anything sweet. Immune to Lankton''s Knot enzyme and acid, and to Faerie Magic. Vulnerability: hooked on sugar and sweets, which act on it like a narcotic. Damage is by spell, psionics or weapon only.', 'Blinding Flash, Befuddle, Blind, Charismatic Aura, Charm, Cleanse, Fools Gold, Heavy Breathing, and Paralysis: Lesser. The usual Faerie Magic rules apply.', 'Minor psionic, I.S.P. 2D6 plus M.E.: Deaden Pain (4), Induce Sleep (4), Suppress Fear (8) and Object Read (6) only.', '6-12 inches (0.15-0.3 m) tall', '8-16 ounces (0.22-0.45 kg)', 'Unknown; possibly immortal', 'Beside rivers, lakes and streams where Lankton''s Knot grows; the Southeast only', 'Other Trysia and, depending on circumstance, other Faerie Folk, particularly the cruel ones. The Lankton''s Knot does not know they exist and is no ally', 'None as such, though it cares little for humans or most other life', 'Optional player character. R.C.C.: creature of magic, free spirit. Uses the Mystic O.C.C. experience table; average level 1D6.', 'A small, butterfly-winged faerie living alongside the carnivorous Lankton''s Knot, whose digestive adhesive it eats as a sweet drug; it lures animals and people into the plant, taunts them, and reads their stolen belongings with Object Read. One that kicks the habit grows kinder, though it stays spiteful and craves honey and candy instead; the colony shuns it.', 'Rifts World Book 26: Dinosaur Swamp p.36-37'),
('lanktons-knot', 'Lankton''s Knot', 'plant', 'rifts', 0, 'Plant; not applicable', '{"IQ":"N/A","ME":"N/A","MA":"N/A","PS":"N/A","PP":"N/A","PE":"N/A","PB":"N/A","Spd":"N/A"}', NULL, NULL, '3', NULL, NULL, 'M.D.C. is typically 3 per square meter of plant; the stored 3 is one square meter. Attributes are not applicable. No P.P.E.', NULL, 5, '{"attacks":3}', 'None. Attacks per melee are effectively 3, counted only to time the acid''s damage. Horror Factor 5, rising to 12 once a trapped victim understands it is dying.', NULL, 'Having no central nervous system, it feels neither pain nor emotion; Critical Strikes and Death Blow do not affect it, and neither do psychic attacks or anything else aimed at mind or feelings. Uses no scent or color lure; the Trysia Faeries bring it prey. Acidic adhesive: anything walking into a patch must make a passive dodge against an attack value of 16 or be stuck fast. The adhesive digests S.D.C. and M.D.C. creatures and structures alike for 4D6 damage per melee attack (about every five seconds); anyone caught is pinned under the Holding rules (Rifts Game Master Guide p.29) and must roll 23 to tear loose, unless companions blast the victim free. The honey-like acid smears rather than wipes off and stays active for 1D4 melee rounds after the victim is free. Vulnerabilities: it cannot dodge or flee, so ranged, fire and area attacks work well.', 'None.', 'None.', 'Varies by patch; each stalk is about 3 feet (0.9 m) tall', 'Varies; typically 3-10 lbs (1.35-4.5 kg) per cluster', 'Unknown; guessed at 50-80 years', 'The delta regions of the east coast, especially the south Georgia coast, along stream banks and lake shores in the south', 'The Trysia Faeries, who guard and feed it to keep their supply of its nectar', 'None', 'None; plant.', 'A weedy colonial plant, a patch of reeds and vines dotted with small, lacy white blossoms, named for the early Wilderness Scout Marcus Sheridan Lankton, whose dewy adhesive traps animals and dissolves them alive into fertilizer, leaving rich dark soil that would farm well if the plant were cleared. Hard to see in the morning, glistening in the afternoon heat. Its enzyme is sought as an area effect weapon, at prices that swing with supply.', 'Rifts World Book 26: Dinosaur Swamp p.37-38'),
('qink', 'Qink', 'plant', 'rifts', 0, 'Plant; not applicable', '{"IQ":"N/A","ME":"N/A","MA":"N/A","PS":"N/A","PP":"N/A","PE":"N/A","PB":"N/A","Spd":"N/A"}', NULL, NULL, '35', NULL, NULL, 'Mega-Damage by location: Fleshy Flower Center 35 (stored as the main body); Digestive Root Pocket 80; Protective Leaves (4) 50 each; Vines (6) 15 each; Thorn Tips (12) 3 each. Attributes are not applicable. No P.P.E.', NULL, 12, '{"attacks":2,"strike":2}', '+2 to strike with its lashing vines.', NULL, 'Having no central nervous system, it feels no pain; Critical Strikes and Death Blow do not affect it, and neither do psychic attacks or anything else aimed at mind or feelings. Pressure-sensitive root tendrils set the six thorn-tipped vines thrashing at anything that steps on them and steer them onto the victim, which is dragged into the central flower and down to the digestive pocket. Poison: a thorn striking an unprotected spot calls for a save vs Poison of 14 or higher (defender wins ties); a failure numbs and paralyzes that area for 1D4 hours, and repeated hits accumulate. Head: blind and mute, -10 to strike, parry and dodge, and sight skills at -80%. One arm: P.P., P.S. and combat bonuses down by a quarter and Spd -4; double that for both arms. One leg: P.P., P.S. and combat bonuses down by a quarter and Spd halved; doubled for both legs. Torso: failing heart and lungs halve combat bonuses, cut P.S., P.P. and P.E. by a third, and leave only short, raspy speech. Digestive pocket: 4D6 M.D. every 6 hours of exposure, numbing the victim; organic matter dissolves, anything under 20 M.D.C. is destroyed, and anything tougher takes 20 M.D. and is eventually spat out, which is why ruined armor and bionics lie around a Qink. Vulnerabilities: cannot dodge, or flee from fire and area effects.', 'None.', 'None.', 'Flower center about 8 feet (2.4 m) across, vines about 14 feet (4.3 m) long, root structure reaching 20 feet (6.1 m) below ground', '600 lbs (270 kg)', 'Unknown; suspected to be 15-30 years', 'The delta regions of the east coast, especially the high magic region of the south Georgia coast', 'None', 'None', 'None; plant.', 'Pronounced kink: the most active carnivorous plant of the region, a big fleshy flower in reds, pinks, oranges and blues whose sweet scent and color draw birds, herbivores and curious explorers within reach of six poison-thorned vines strong enough to peel a man out of M.D.C. body armor. Its toxin is prized as a tranquilizer at about 8,000 credits a dose, though dealers and Alchemists pay no more than a tenth of that.', 'Rifts World Book 26: Dinosaur Swamp p.38-39'),
('seep-fern', 'Seep Fern', 'plant', 'rifts', 0, 'Plant; not applicable', '{"IQ":"N/A","ME":"N/A","MA":"N/A","PS":"N/A","PP":"N/A","PE":"N/A","PB":"N/A","Spd":"N/A"}', NULL, '3D6', NULL, NULL, NULL, 'S.D.C. is 3D6 per square meter; the stored 3D6 is one square meter. Attributes are not applicable. No P.P.E.', NULL, 7, '{"attacks":0}', 'None. Attacks per melee are effectively zero.', NULL, 'Having no central nervous system, it feels no pain; Critical Strikes and Death Blows do not affect it, and neither do psychic attacks or anything else aimed at mind or feelings. Its leaves seep a sedative that smells like fresh blood; an animal that breathes it within 3 feet (0.9 m) or licks it must save vs Poison of 16 or higher or fall unconscious for 1D4 hours. Shallow roots then rise, enter the sleeper through any opening, keep it sedated with the same toxin and drain 3D6 damage of blood per hour until the plant is full or the victim dies; a plant holds 1D6x10 points of blood every 24 hours, so a first feeding is not always fatal, though few animals survive. Vulnerabilities: cannot dodge, or flee from fire and other area effects.', 'None.', 'None.', 'Varies by colony; each plant is about 2 feet (0.6 m) tall', 'Insignificant', 'Unknown', 'The delta regions of the east coast, especially the south Georgia coast, in small colonies among ordinary ferns', 'None', 'None', 'None; plant.', 'A bushy, fern-like plant (not a true fern) whose leaves look smeared with a wounded animal''s blood, drawing predators and scavengers in to investigate. Barbarians and Wilderness Scouts collect the sedative for hunting and other uses; it sells for 100 credits a single-dose vial or 900 for ten, and loses all potency within 12 days.', 'Rifts World Book 26: Dinosaur Swamp p.40'),
('tunnel-goblins', 'Tunnel Goblins', 'humanoid', 'rifts', 0, 'Uncertain; presumed Aberrant evil, given their hostility to outsiders and loyalty to the clan', '{"IQ":"1D6+7","ME":"2D6","MA":"1D6","PS":"1D6+16","PP":"1D6+12","PE":"1D10+12","PB":"1D4","Spd":"1D6+6"}', NULL, NULL, '5D6+40', 'PE', NULL, 'Stored figures are a Warrior''s. M.D.C.: Leader 6D6+60, Warriors 5D6+40. P.P.E.: the Leader/Earth Wizard has P.E. x5 plus 1D6+6 per level of experience; Warriors/Drones have their P.E. number plus 1D6 per level. Supernatural P.S. and P.E. Also known as Clay Men.', NULL, 13, '{"attacks":5,"initiative":2,"strike":2,"parry":1,"dodge":1}', '+2 on initiative (underground only), +2 to strike, +1 to parry and dodge, +8 to save vs poisons, toxins and drugs, +2 to save vs Horror Factor, +3 to save vs possession and mind control; impervious to toxic gas, smoke and cold. In addition to possible attribute bonuses. Attacks per melee: five physical, or two by magic.', 'R.C.C. skills of note: Camouflage (+10%), Climbing (+20% on earth and stone, halved on other surfaces), Dowsing (+10%), Escape Artist (+20%), Gemology (+20%), Land Navigation (+20% underground only), Prowl, Spelunking (+15%), Tracking, Wrestling, W.P. Blunt, W.P. Small Thrown Weapons (rocks included). Average level of experience: 1D6+3 for the Leader, 1D4+1 for Warriors.', 'Nightvision 300 feet (91 m) even in total darkness but only 20 feet (6.1 m) of day vision; excellent hearing; digs through soft earth at 10 feet (3 m) a minute; holds its breath 20 minutes; toxic fumes and gases barely affect it; heals three times as fast as a human. Special Turn into Soft Clay: to escape, hide (+20% to Camouflage) or ambush (+10% to Prowl) it becomes a mound of humanoid-shaped clay that cannot attack, move or cast magic but still senses what is around it. In clay form it is impervious to all attacks, and even blown apart it re-forms and changes back. Each change costs two melee attacks and can be made at will while attacks remain. While in clay form the Earth Wizard alone is mobile, oozing at half Spd along floors, walls and tunnel roofs.', 'Only the Leader/Earth Wizard: the Earth Warlock spells Animate Plants (10), Chameleon (5), Clay to Stone (20), Crumble Stone (10), Dirt to Clay (6), Earth Rumble (10), Hopping Stones (6), Mystic Fulcrum (3), Repel Animals (10), Rock to Mud (6), Rot Wood (4) and Wall of Clay (8), plus 1D6+1 more chosen from Earth spells of levels 1-4.', NULL, 'Leader 6 feet (1.8 m); Warriors 5 feet (1.5 m)', NULL, NULL, 'Only the tunnels under the ruined theme park of the Castle Kingdom in Florida; numbers unknown, perhaps 100 or fewer, perhaps far more', NULL, NULL, 'None; a clan of a Leader (shaman or Earth Wizard) and Warriors or drones. Equipment: blunt stone or wooden weapons, plus rocks to throw (1D4 M.D.).', 'Hunched, barrel-chested alien humanoids with mottled grey-white skin shedding in flakes, big clawed three-fingered hands, glossy black beetle eyes, a slitted nose and broken, jagged teeth, named by the explorer Neenok when they drove his expedition out of the Jungle Castle tunnels. They speak, if at all, in raspy growls and whispers, but seem nearly as smart as humans. Their leader has a much larger head and casts Elemental Magic; no female has been seen.', 'Rifts World Book 26: Dinosaur Swamp p.112-113'),
('rat-men-of-atlanta', 'Rat Men of Atlanta', 'mutant', 'rifts', 0, 'Any, but typically Scrupulous, Unprincipled or Anarchist', '{"IQ":"2D6+6","ME":"1D6+8","MA":"2D6+6","PS":"1D6+10","PP":"2D6+8","PE":"2D6+6","PB":"1D6+6","Spd":"3D6+14"}', 'PE+2D6', '3D6+6', NULL, '3D6', NULL, 'Hit Points are P.E. +2D6, plus 1D10 per level of experience. S.D.C. 3D6+6 is a bonus on top of what the O.C.C. and physical skills give. M.D.C. only by body armor. P.B. 1D6+6 is as humans see it. Spd 3D6+14, rolling an extra 1D6 when the first roll is the maximum.', NULL, NULL, '{"initiative":1,"dodge":1,"roll":1,"pull_punch":2}', 'Special bonuses: +1 on initiative, +1 to dodge, +2 to pull punch, +1 to roll with impact; -2 to save vs Horror Factor. In addition to possible attribute bonuses. Attacks per melee are by O.C.C.', 'Swimming 80%, Climbing 80%.', 'Nightvision 100 feet (30.5 m), keen hearing, and natural swimmers and climbers. Otherwise about as physically capable as a human, fighting with weapons. Vulnerabilities: timid and short of self-confidence.', 'None.', 'None.', 'Females 5 to 5.5 feet (1.5-1.7 m), males 5.5 to 6 feet (1.7-1.8 m); females are a little smaller and slimmer', '80-140 lbs (36-63 kg)', '30-42 years, though most die violently and it may be half again as long', 'Only Atlanta, Georgia, in the northern tunnels of the old metro system under the ruins', 'Their own people; long hidden from everyone, they are only now reaching out to other humanoids', 'Nearly everyone and everything', 'Race unknown; possibly mutated rats. O.C.C. odds: Vagabond 78%, Bandit/Thief 10%, Wilderness Scout 10%, Holistic Healer 2% (usually a female); any extra O.C.C. Related and Secondary Skills they get are halved. Typical experience level 1D4.', 'Humanoids covered in coarse grey hair, with rat-like heads, small round ears, a long naked tail and human hands, feet and voices, who usually wear shirts, vests or jackets, boots and utility belts. Perhaps lab rats mutated before the Cataclysm, they live by hunting, scavenging and stealing at Stone Age level, and barbarian tribes hunt them for fur and meat. A plague two years ago cut nearly 5000 to about 460; the survivors now follow their self-made King Hirgg, who is courting the Eleytherian Atlanteans. Only one in six owns a working Mega-Damage weapon.', 'Rifts World Book 26: Dinosaur Swamp p.121-122');
