-- Rifts World Book 26: Dinosaur Swamp - its bestiary and its notable NPCs.
-- 21 creatures (migration 074) and 0 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~251-dinosaur-swamp-creatures.sql
--
-- Written by scripts/bestiary-sql.mjs from 8 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.




-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 21 creatures are in' AS assertion, count(*) AS got, 21 AS want
  FROM creatures WHERE slug IN ('allosaurus', 'ankylosaurus', 'dilophosaurus', 'pachycephalosaurus', 'sarcosuchus', 'sauropod', 'scampers', 'spinosaurus', 'stegosaurus', 'azhures', 'haunting-child', 'iron-hoof', 'panthera-thrinax', 'spitfire-leaper', 'switchback', 'trysia-faerie', 'lanktons-knot', 'qink', 'seep-fern', 'tunnel-goblins', 'rat-men-of-atlanta');
SELECT 'and 1 of them are playable' AS assertion, count(*) AS got, 1 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('allosaurus', 'ankylosaurus', 'dilophosaurus', 'pachycephalosaurus', 'sarcosuchus', 'sauropod', 'scampers', 'spinosaurus', 'stegosaurus', 'azhures', 'haunting-child', 'iron-hoof', 'panthera-thrinax', 'spitfire-leaper', 'switchback', 'trysia-faerie', 'lanktons-knot', 'qink', 'seep-fern', 'tunnel-goblins', 'rat-men-of-atlanta');
SELECT 'the creatures carry 75 attacks' AS assertion, count(*) AS got, 75 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('allosaurus', 'ankylosaurus', 'dilophosaurus', 'pachycephalosaurus', 'sarcosuchus', 'sauropod', 'scampers', 'spinosaurus', 'stegosaurus', 'azhures', 'haunting-child', 'iron-hoof', 'panthera-thrinax', 'spitfire-leaper', 'switchback', 'trysia-faerie', 'lanktons-knot', 'qink', 'seep-fern', 'tunnel-goblins', 'rat-men-of-atlanta');

